import React from 'react';

function Experience() {
  return (
    <section id="experience">
      <h2 className="section-heading">Experience</h2>
      <ul className="experience-list">
        <li><strong>Undergraduate Research Assistant</strong> – Texas State University (Jul 2024 – Present)</li>
        <li><strong>Web & Social Media Intern</strong> – The Teacher Reuse (Jan 2024 – May 2024)</li>
        <li><strong>Student Fellow</strong> – MathWorks Camp (Jun 2024)</li>
      </ul>
    </section>
  );
}

export default Experience;
